function onLessonDetection(detected,count){if(!practiceNodes||modal.hidden)return;practiceNodes.handCount.textContent=count?count+' '+(count===1?'MANO':'MANOS'):'SIN MANOS';const now=performance.now();if(detected&&lastDetectedAt&&now-lastDetectedAt<=500)detectedMs+=Math.min(now-lastDetectedAt,150);lastDetectedAt=detected?now:0;const ratio=Math.min(1,detectedMs/detectionTargetMs);practiceNodes.progress.style.width=(ratio*100)+'%';practiceNodes.time.textContent=(detectedMs/1000).toFixed(1);if(ratio>=1){practiceNodes.next.disabled=false;practiceNodes.status.textContent='¡Mano visible! Ya puedes continuar.';quizFeedback.textContent='¡Listo! Confirmamos que tu mano está dentro del encuadre.';quizFeedback.className='quiz-feedback good';practiceNodes.next.textContent=quizIndex===quizQuestions.length-1?'Ver cierre de práctica →':'Siguiente seña →'}}
